pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address lender, address to, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public {
        // Restrict inputs to avoid reverts and ensure a loan can be created
        amount = bound(amount, 1, 1e30);
        loanToCollateral = bound(loanToCollateral, 1, 1e30);
        interest = bound(interest, 0, 1e18);
        duration = bound(duration, 1 days, 365 days);
        vm.assume(to != address(0));
        vm.assume(lender != address(0));

        // Create a loan: first request, then clear
        vm.prank(lender);
        c.requestLoan(amount, interest, loanToCollateral, duration);
        c.clearRequest(0, false, false);

        // Get the lender of loan 0
        (,,,,, address originalLender,,) = c.getLoan(0);

        // Attempt to approve transfer from someone else (not original lender)
        vm.prank(address(0xdead));
        (bool success,) = address(c).call(abi.encodeWithSignature("approveTransfer(address,uint256)", to, 0));

        // If the call reverted, no change; if it succeeded, check lender unchanged
        if (success) {
            (,,,,, address newLender,,) = c.getLoan(0);
            assertTrue(newLender == originalLender, "Lender should not change");
        } else {
            (,,,,, address newLender,,) = c.getLoan(0);
            assertTrue(newLender == originalLender, "Lender should not change after revert");
        }
    }
}

